@js:
var key = java.hexDecodeToString(result);
var kw = encodeURIComponent(key + ' 小说封面');
var urls = [
    `https://pre-api.tuishujun.com/api/searchBook?search_value=${key}&page=1&pageSize=20`,
    `http://m.ypshuo.com/api/novel/search?keyword=${key}&searchType=1&page=1`,
    `https://image.baidu.com/search/acjson?tn=resultjson_com&word=${kw}&pn=0&rn=15`,
    `https://cn.bing.com/images/search?q=${kw}&form=HDRSC2`
];
var rs = java.ajaxAll(urls).map(r => r.body());
function jjson(str, rule) {
    try {
        return com.jayway.jsonpath.JsonPath.read(str, rule);
    } catch (e) {
        return [];
    }
}
var rr1 = jjson(rs[0], '$.data.data[*]');
var rr2 = jjson(rs[1], '$.data.data[*]');
var na = String(book.name),
    au = String(book.author);
var list = [];
for (let c of rr1) {
    //本地书名包含搜索结果书名
    if (na.includes(c.title + '')) {
        let au2 = c.author_nickname + '';
        //作者匹配
        if (au.includes(au2) || au2.includes(au)) list.push(c.cover);
    }
}
for (let c of rr2) {
    if (na.includes(c.novel_name + '')) {
        let au2 = c.author_name + '';
        if (au.includes(au2) || au2.includes(au)) list.push(c.novel_img);
    }
}
//百度图片
for (let u of jjson(rs[2], '$.data[*].thumbURL')) list.push(u);
//必应图片
var html = String(rs[3] || '').replace(/&quot;/g, '"');
var re = /"murl":"(.*?)"/g, m;
while ((m = re.exec(html)) !== null && list.length < 40) list.push(m[1].replace(/\\/g, ''));
list.filter(x => x).join('\n')
